```html
<div class="expense-voucher">

    {% if doc.status != "Approved" and doc.status != "Reimbursed" %}
        <div class="pending-banner">
            PENDING APPROVAL — NOT YET REIMBURSABLE
        </div>
    {% endif %}

    <h1>Expense Claim Voucher</h1>

    <div class="employee-section">
        <p><strong>Employee:</strong> {{ doc.employee }}</p>
        <p><strong>Department:</strong> {{ doc.department }}</p>
        <p><strong>Expense Date:</strong> {{ doc.expense_date }}</p>
    </div>

    <hr>

    <table class="expense-table">
        <thead>
            <tr>
                <th>Expense Category</th>
                <th>Description</th>
                <th>Amount</th>
            </tr>
        </thead>

        <tbody>
            {% for row in doc.expense_lines %}
            <tr>
                <td>{{ row.expense_category }}</td>
                <td>{{ row.description }}</td>
                <td>{{ frappe.utils.fmt_money(row.amount, currency=doc.currency) }}</td>
            </tr>
            {% endfor %}
        </tbody>
    </table>

    <div class="total-section">
        <strong>
            Total Amount:
            {{ frappe.utils.fmt_money(doc.total_amount, currency=doc.currency) }}
        </strong>
    </div>

</div>

<style>
    @page {
        size: Letter;
        margin: 20mm;
    }

    .expense-voucher {
        font-family: Arial, sans-serif;
        font-size: 12px;
    }

    .pending-banner {
        background-color: #fff3cd;
        border: 1px solid #ffeeba;
        padding: 10px;
        text-align: center;
        font-weight: bold;
        margin-bottom: 20px;
    }

    h1 {
        text-align: center;
        margin-bottom: 25px;
    }

    .employee-section p {
        margin: 5px 0;
    }

    hr {
        margin: 20px 0;
    }

    .expense-table {
        width: 100%;
        border-collapse: collapse;
        margin-top: 15px;
    }

    .expense-table th,
    .expense-table td {
        border: 1px solid #000;
        padding: 8px;
        text-align: left;
    }

    .expense-table th {
        font-weight: bold;
    }

    .expense-table td:last-child,
    .expense-table th:last-child {
        text-align: right;
    }

    .total-section {
        text-align: right;
        font-size: 18px;
        margin-top: 20px;
    }
</style>
```
